"""П-42 v2: отчёт `docs/findings/p42-level-breakout-v2-2026-11-14.md` из JSON-результатов (числа не набираются руками).

  P42_ROOT=data/p42v2 python tools/p42/make_doc_v2.py > docs/findings/p42-level-breakout-v2-2026-11-14.md
Читает: report.json (шаг A, 1м), report-tick-tickfull8.json (шаг B, после правки разбора цен), report-tick-tickfull-v7.json (до правки),
report-reentry.json (§13.5), outsiders-summary.json, outsiders-excl.json.
"""
import json
import os

ROOT = os.environ.get("P42_ROOT", "data/p42v2")


def J(name):
    return json.load(open(os.path.join(ROOT, name), encoding="utf-8"))


def n(x, d=2, sign=True):
    s = ("%+." + str(d) + "f") % x if sign else ("%." + str(d) + "f") % x
    return s.replace("-", "−").replace(".", ",")


def ci(h):
    return "%s [%s; %s]" % (n(h["mean"]), n(h["lo"]), n(h["hi"]))


def cell(h):
    return "%s, n=%d (%s/сут.)" % (ci(h), h["trades"], n(h["trades_per_day"], 2, False))


def verdict_ru(v):
    return v


SIDE = {"long": "Лонг", "short": "Шорт"}


def table_cands(res, names, title_map):
    out = ["| кандидат | половина A (15.09–14.10) | половина B (15.10–13.11) | вердикт §10 |", "|---|---|---|---|"]
    for k in names:
        c = res["cand"].get(k)
        if not c:
            continue
        a, b = c["halves"]["A"], c["halves"]["B"]
        out.append("| %s | %s | %s | %s |" % (title_map.get(k, k), cell(a), cell(b), c["verdict"]))
    return "\n".join(out)


def main():
    A = J("report.json")
    T = J("report-tick-tickfull8.json")
    T7 = J("report-tick-tickfull-v7.json")
    R = J("report-reentry.json")
    OS = J("outsiders-summary.json")
    EX = J("outsiders-excl.json")
    p = []
    w = p.append

    w("# П-42 версия 2 (универсум ≥ $12 млн, 566 монет; вход и выходы по сделкам Binance): пробой часового уровня, лонг и шорт отдельно — отчёт (14.11.2026)\n")
    w("**Вердикт одной строкой (измерено, 60 суток 15.09–13.11, $500 на сделку, тариф владельца, проскальзывание 1 bp):**")
    la, lb = T["long"]["cand"]["base"]["halves"]["A"], T["long"]["cand"]["base"]["halves"]["B"]
    sa, sb = T["short"]["cand"]["base"]["halves"]["A"], T["short"]["cand"]["base"]["halves"]["B"]
    w("- **Лонг — опровергнуто и на минутках, и на сделках.** Минутки (шаг A): база %s в A и %s в B $/сут.; сделки (шаг B): база %s в A и %s в B. Перекрёстный кандидат — 0 сделок в обеих половинах на обоих шагах (принятые значения ведут к «не торговать»). Края нет." % (
        n(A["long"]["cand"]["base"]["halves"]["A"]["mean"]), n(A["long"]["cand"]["base"]["halves"]["B"]["mean"]), n(la["mean"]), n(lb["mean"])))
    w("- **Шорт — не подтверждён ни одним кандидатом; шаги расходятся.** Минутки: база %s / %s (не ясно), перекрёстный %s / %s (не ясно). Сделки: база **опровергнута** (A %s, B %s; B-интервал целиком ниже 0), перекрёстный %s / %s (не ясно), все три варианта топ-3 — опровергнуты. Положительный знак минутной базы на сделках не воспроизводится." % (
        n(A["short"]["cand"]["base"]["halves"]["A"]["mean"]), n(A["short"]["cand"]["base"]["halves"]["B"]["mean"]),
        n(A["short"]["cand"]["crossfit"]["halves"]["A"]["mean"]), n(A["short"]["cand"]["crossfit"]["halves"]["B"]["mean"]),
        n(sa["mean"]), n(sb["mean"]),
        n(T["short"]["cand"]["crossfit"]["halves"]["A"]["mean"]), n(T["short"]["cand"]["crossfit"]["halves"]["B"]["mean"])))
    w("- **Повторный вход по уровню (§13.5, оба варианта) ничего не меняет:** повторы — 0–3 % сделок; вердикты те же, ни один кандидат не подтверждён.")
    w("- **Абсолютные аутсайдеры** найдены и перечислены (раздел ниже; CSV `data/p42v2/outsiders-{long,short}.csv`); вне выборки, где они выбраны, их исключение базу не улучшает (|Δ| ≤ $2,6/сут., почти все интервалы накрывают 0).")
    w("- **3,4 млн «плохих строк» aggTrades (0,6 %) выяснены:** это цены меньше 0,001 в записи `9.16E-4`; после правки разбора — 0 плохих строк, вердикты не изменились.\n")
    w("Числа — **измерено** на Binance USD-M. «Опровергнуто»/«не ясно» — по правилу §10 протокола `docs/research/P-42-level-breakout.md` (дополнен §13), Холм — по накопленному счётчику испытаний (лонг 207, шорт 199). Всё «найдено на этих данных»: ни одной проверки на новых сутках; демо-ожидание «после издержек», не прогноз.\n")

    w("## Протокол и данные")
    w("- Протокол: `docs/research/P-42-level-breakout.md` §13 (записан и закоммичен до счёта: `2356b172`; §13.5 «повторный вход» — `d1b86074` и `d24226a2`, тоже до счёта). Слова владельца 14.11: «надо грузить от 12 млн суточного объема»; «да давай для бинанса агтрейды»; про вариант с повторным входом — «ну сделай».")
    w("- Универсум шага A: **566** бессрочных Binance USD-M с оборотом ≥ $12 млн хотя бы в один день 01.09–13.11 (227 прежних + 339 новых). Окна: прогрев 01.09–14.09, A 15.09–14.10, B 15.10–13.11 (по 30 суток).")
    w("- Шаг B: сделки `aggTrades` (`transact_time` в мс, цена как в файле), 566 монет; вход — следующая агрессивная сделка стороны (± 1 bp), тейки — только строго через цену, стоп — по цене пробившей сделки (§13.2).")
    w("- Код: ветка `bb/42-v2-finish-v1-thr_7cy3ypv2kx` (от `bb/42-rerun-12m-ticks-v1-thr_fefbsq7ncj` @ e0539507); модуль `src/breakout/` (`tick.rs`, 1238 тестов, clippy `-D warnings`, fmt — зелёные на srv). Бинари на srv `/data/p42v2/bin/alpha-p42-v{5…10}`; результаты — `/data/p42v2/out/`, локально `data/p42v2/` (gitignored).\n")

    # ---------------- шаг A
    w("## Шаг A: минутки, 566 монет")
    for side in ("long", "short"):
        r = A[side]
        w("### %s" % SIDE[side])
        w("Испытаний шага A: %d (v1 %d + v2 %d); Холм по накопленному m = %d, z = %s; PBO %s (%d конфигураций)." % (
            r["m_package"], r["prior_trials"], r["trials"], r["m_package"], n(r["z_holm"], 2, False), n(r["pbo"]["pbo"], 2, False), r["pbo"]["configurations"]))
        names = [k for k in ("base", "crossfit", "letter") if k in r["cand"]]
        if side == "short" or r["cand"]["letter"]["halves"]["A"]["mean"] != 0 or True:
            pass
        w(table_cands(r, [k for k in names if not (k == "letter" and r["cand"]["letter"]["verdict"] == r["cand"]["crossfit"]["verdict"] and r["cand"]["letter"]["halves"]["A"]["mean"] == r["cand"]["crossfit"]["halves"]["A"]["mean"])],
                      {"base": "база (правила витрины)", "crossfit": "перекрёстный (значения из другой половины)", "letter": "«по букве» протокола (справочно)"}))
        w("")
        b = r["cand"]["base"]["halves"]
        w("База: после первого дня монеты с оборотом ≥ $12 млн — A %s, B %s $/сут.; прежние 227 монет — A %s, B %s; новые 339 — A %s, B %s." % (
            n(b["A"]["after_first_day"]["mean"]), n(b["B"]["after_first_day"]["mean"]), n(b["A"]["old_coins"]), n(b["B"]["old_coins"]), n(b["A"]["new_coins"]), n(b["B"]["new_coins"])))
        w("Без 2 лучших суток: A %s, B %s; без 2 лучших монет: A %s, B %s.\n" % (
            n(b["A"]["no_best2_days"]["mean"]), n(b["B"]["no_best2_days"]["mean"]), n(b["A"]["no_best2_coins"]["mean"]), n(b["B"]["no_best2_coins"]["mean"])))

    # ---------------- шаг B
    w("## Шаг B: вход и выходы по сделкам")
    tm = {"base": "тик-база (lat 0, 1 bp)", "crossfit": "тик-перекрёстный", "top:v_n_bounce_3": "топ-3: n_bounce=3", "top:v_e_0p1": "топ-3: e=0,1",
          "top:v_tf_240": "топ-3: tf=240", "top:j_be_0__t_low_2": "топ-3: be=0, t_low=2", "top:v_be_0": "топ-3: be=0", "top:j_be_0__t_low_3": "топ-3: be=0, t_low=3"}
    for side in ("long", "short"):
        r = T[side]
        w("### %s" % SIDE[side])
        w("Испытаний шага B: %d (база 1 + перекрёстный 2 + топ-3); накопленный m = %d (шаг A %d), z Холма = %s. Топ-3 — отбор на тех же данных («найдено на этих данных»), справочно." % (
            r["n_step_b"], r["m"], r["m_step_a"], n(r["z_holm"], 2, False)))
        w(table_cands(r, list(r["cand"].keys()), tm))
        w("")
        w("Задержка входа и проскальзывание (справочно, не испытания; $/сут., [95 %], сделок):")
        w("")
        w("| вариант | A | B |")
        w("|---|---|---|")
        for k, v in r["sens"].items():
            if v["statA"]["trades"] == 0 and v["statB"]["trades"] == 0:
                continue
            nm = k.replace("b0_", "база ").replace("cross_", "перекрёстный ").replace("lat", "задержка ").replace("slip", "проскальзывание ")
            w("| %s | %s [%s; %s], n=%d | %s [%s; %s], n=%d |" % (nm, n(v["A"]), n(v["statA"]["lo"]), n(v["statA"]["hi"]), v["statA"]["trades"], n(v["B"]), n(v["statB"]["lo"]), n(v["statB"]["hi"]), v["statB"]["trades"]))
        w("")
    w("**Минутки против сделок (база).** Сделок в 3–4 раза больше (лонг A: 86 → 344, B: 106 → 373; шорт A: 76 → 311, B: 70 → 313), потому что сигнал стоит на первом подходе в зону внутри минутки — в том числе в минутках, которые потом пересекают уровень (1м такие пропускает). Шорт на минутках около нуля (%s / %s), на сделках — минус, особенно в B (%s): доля стопов шорта выросла с %.1f %% / %.1f %% (1м, A/B) до 9 %% / 17 %% (сделки). Пример из разбора предыдущего прогона (TAKEUSDT, не пересчитан): вход по нижней сделке «флеш-вика» (свип 5 %% за 1 мс), стоп через 1 мс, −$25 — артефакт нулевой задержки; при задержке 250/1000 мс шорт-убыток в B сокращается до %s / %s, но знак остаётся отрицательным." % (
        n(A["short"]["cand"]["base"]["halves"]["A"]["mean"]), n(A["short"]["cand"]["base"]["halves"]["B"]["mean"]), n(sb["mean"]),
        A["short"]["cand"]["base"]["halves"]["A"]["stop_share"] * 100, A["short"]["cand"]["base"]["halves"]["B"]["stop_share"] * 100,
        n(T["short"]["sens"]["b0_lat250"]["B"]), n(T["short"]["sens"]["b0_lat1000"]["B"])))
    w("Лонг при задержке 250/1000 мс: A %s / %s, B %s / %s — интервалы накрывают 0, знак «−» во всех клетках; при проскальзывании 0 → 5 bp база лонга %s → %s в A.\n" % (
        n(T["long"]["sens"]["b0_lat250"]["A"]), n(T["long"]["sens"]["b0_lat1000"]["A"]), n(T["long"]["sens"]["b0_lat250"]["B"]), n(T["long"]["sens"]["b0_lat1000"]["B"]),
        n(T["long"]["sens"]["b0_slip0"]["A"]), n(T["long"]["sens"]["b0_slip5"]["A"])))

    # ---------------- плохие строки
    w("## Строки aggTrades, которые не читались (3,4 млн → 0)")
    w("- **Что это.** Binance пишет цены меньше 0,001 в Java-записи с экспонентой (`9.16E-4`, `5.996E-5`); разбор `parse_dec` принимал только десятичную запись и отбрасывал такие строки. Не заголовок (заголовки — по одному на файл — пропускаются отдельно), не смена схемы (0 строк с числом полей ≠ 7, 0 с нецелым временем), не пустые строки.")
    w("- **Масштаб.** Базовый прогон v6 — 3,43 млн из 556 млн строк (0,6 %); полный прогон v7 — 4 992 063 из 708 371 498 строк, прочитанных на фазе 1 (0,70 %); после правки (v8) — **0** плохих строк, разобрано 708 371 498.")
    w("- **Какие монеты.** 18 бессрочных, у которых минутный минимум хоть раз был ниже 0,001: IOST (10,06 млн строк с экспонентой из 27,0 млн), VTHO (9,51 из 9,86 млн), HOT (4,63), BOME (4,51 из 6,52), TAG (4,03), NEIRO (3,90), PTB (3,62 из 5,99; 53 файла), XPIN (2,36), NOT (2,33), DOGS (2,27), MEW (2,04), SLP (1,47), SPELL (1,23), ONE (1,07 из 56,5), HMSTR (1,04), CKB (0,22), TAC (0,11), TLM (0,007). Полный просмотр всех 1311 файлов этих монет: 54,4 млн из 139,2 млн строк в записи с экспонентой, других отклонений нет. Частичный полный просмотр (9,6 тыс. файлов всех монет) других монет с недесятичной ценой не нашёл. Остальные 548 монет — цены ≥ 0,001, их строки читались целиком.")
    w("- **Влияние на результат.** Базовый лонг +8 сделок (IOST 4, PTB 2, HOT 1, VTHO 1; −$11,7 за 60 суток), базовый шорт +8/−2 сделки (+$11,5 / −$11,8). Числа базы до/после правки: лонг A %s → %s, B %s → %s; шорт A %s → %s, B %s → %s ($/сут.). Вердикты не изменились; v7-числа сохранены (`report-tick-tickfull-v7.json`). Правка — `parse_px` в `src/breakout/tick.rs` (тест `csv_parse_java_exponent_prices`); минутный разбор не затронут (там такие записи привели бы к ошибке загрузки, ошибок не было).\n" % (
        n(T7["long"]["cand"]["base"]["halves"]["A"]["mean"]), n(la["mean"]), n(T7["long"]["cand"]["base"]["halves"]["B"]["mean"]), n(lb["mean"]),
        n(T7["short"]["cand"]["base"]["halves"]["A"]["mean"]), n(sa["mean"]), n(T7["short"]["cand"]["base"]["halves"]["B"]["mean"]), n(sb["mean"])))

    # ---------------- повторный вход
    w("## Повторный вход по уровню (§13.5)")
    w("Правило v2 (§5.1): «одна сделка на уровень — любой выход расходует уровень». Вариант 1 (`reentry=1`): тейки, безубыток, трейл и принудительное закрытие уровень не расходуют, расходует только жёсткий стоп. Вариант 2 (`reentry=2`, ближе к тексту бота: забывает уровень только ложный пробой): выходы уровень не расходуют вовсе. Ложный и истинный пробой — как раньше. Тик-движок, база и перекрёстный кандидат, lat 0 (справочно 250/1000). Испытаний +3 +3 на сторону; Холм m = %d / %d; «найдено на этих данных». Контроль: `b0` и вариант 1 из бинарей v8/v9/v10 побайтово равны.\n" % (R["long"]["m"], R["short"]["m"]))
    for side in ("long", "short"):
        r = R[side]
        w("### %s" % SIDE[side])
        rows = ["| вариант | A | B | вердикт | повторов (A/B) |", "|---|---|---|---|---|"]
        for k, c in r["cand"].items():
            nm = k.replace("reentry1", "вариант 1").replace("reentry2", "вариант 2").replace("перекрёстный", "перекрёстный")
            rp = c["repeats"]
            rows.append("| %s | %s | %s | %s | %.0f %% / %.0f %% |" % (nm, cell(c["halves"]["A"]), cell(c["halves"]["B"]), c["verdict"], rp["A"]["repeat_share"] * 100, rp["B"]["repeat_share"] * 100))
        w("\n".join(rows))
        w("")
    w("Почему повторов мало: после выхода по тейку/трейлу цена выше уровня, после жёсткого стопа — на ≈5 % ниже; повтор требует возврата цены в зону ≤ 0,3 % под уровнем при зелёной минутке и живом уровне. Задержка 250/1000 мс — в `report-reentry.json`; знаки те же.\n")

    # ---------------- аутсайдеры
    w("## Абсолютные аутсайдеры (приказ владельца 14.11)")
    w("Владелец: «собери список абсолютных аутсайдеров. возможно будут монеты которые в минусе на всех клетках. отдельно лонг отдельно шорт». **Найдено на этих данных, описательно, без новых испытаний.** «Клетка» = вариант движка, в котором у монеты есть сделки: 1м — все варианты шага A (122 у лонга, 120 у шорта); тик — 26 клеток стороны из `tick-tickfull8` (кандидаты, топ-3, lat/slip: клетки с lat/slip делят сделки, поэтому «100 %» на тиках мягче, чем выглядит). Класс определяется при ≥ 5 клетках монеты: «100 %» — в минусе во всех своих клетках, «90 %» — в минусе в ≥ 90 %, но не в 100 %. Сделки и $ — суммы по клеткам (сделка в k клетках считается k раз); «база» — только `b0`. Полные списки: `data/p42v2/outsiders-long.csv`, `outsiders-short.csv` (копия в `data/p42/`).\n")
    w("| сторона / движок | монет со сделками | монет ≥ 5 клеток | 100 %: монет, сделок, $ (база: сделок, $) | 90 %: монет, сделок, $ (база $) |")
    w("|---|---|---|---|---|")
    import csv
    for side in ("long", "short"):
        rows = list(csv.DictReader(open(os.path.join(ROOT, "outsiders-%s.csv" % side), encoding="utf-8")))
        for eng in ("1m", "tick"):
            s = OS["%s|%s" % (side, eng)]
            r100 = [x for x in rows if x["engine"] == eng and x["class"] == "100"]
            r90 = [x for x in rows if x["engine"] == eng and x["class"] == "90"]
            w("| %s, %s | %d | %d | %d, %d, −$%s (%d, %s) | %d, %d, −$%s (%s) |" % (
                SIDE[side], "1м" if eng == "1m" else "тик", s["coins_with_trades"], s["coins_ge_minc"], len(r100), sum(int(x["trades_sum_cells"]) for x in r100),
                "{:,.0f}".format(-sum(float(x["net_sum_cells"]) for x in r100)).replace(",", " "), s["base_trades_o100"], ("−$%s" % "{:,.0f}".format(-s["base_net_o100"])).replace(",", " "),
                len(r90), sum(int(x["trades_sum_cells"]) for x in r90), "{:,.0f}".format(-sum(float(x["net_sum_cells"]) for x in r90)).replace(",", " "), ("−$%s" % "{:,.0f}".format(-s["base_net_o90"])).replace(",", " ")))
